import {Vector3,Quaternion} from './vendor/three.module.js';
const X=new Vector3(1,0,0),GOAL=new Quaternion().setFromAxisAngle(new Vector3(0,1,0),Math.PI/2);
function linear(A,b){const n=6,m=A.map((r,i)=>[...r,b[i]]);for(let k=0;k<n;k++){let p=k;for(let i=k+1;i<n;i++)if(Math.abs(m[i][k])>Math.abs(m[p][k]))p=i;[m[k],m[p]]=[m[p],m[k]];const v=m[k][k];if(Math.abs(v)<1e-12)return Array(n).fill(0);for(let j=k;j<=n;j++)m[k][j]/=v;for(let i=0;i<n;i++)if(i!==k){const f=m[i][k];for(let j=k;j<=n;j++)m[i][j]-=f*m[k][j];}}return m.map(r=>r[n]);}
export class RobotKinematics{
 constructor(meta){this.meta=meta;this.joints=meta.joints.map(j=>({...j,originV:new Vector3(...j.origin),axisV:new Vector3(...j.axis)}));this.q=[-1.5,-.2,.1,0,1.67,-1.5];this.lastError=0;this.lastAngle=0;}
 fk(q){const p=new Vector3(),r=new Quaternion(),positions=[],axes=[];for(let i=0;i<6;i++){const j=this.joints[i];p.add(j.originV.clone().applyQuaternion(r));positions.push(p.clone());axes.push(j.axisV.clone().applyQuaternion(r));r.multiply(new Quaternion().setFromAxisAngle(j.axisV,q[i]));}return {p:p.clone().add(X.clone().multiplyScalar(this.meta.tcpOffset).applyQuaternion(r)),r,positions,axes};}
 error(q,target){const state=this.fk(q),e=target.clone().sub(state.p),qr=GOAL.clone().multiply(state.r.clone().invert());if(qr.w<0){qr.x*=-1;qr.y*=-1;qr.z*=-1;qr.w*=-1;}const angle=2*Math.acos(Math.max(-1,Math.min(1,qr.w))),n=Math.hypot(qr.x,qr.y,qr.z),o=n<1e-9?new Vector3():new Vector3(qr.x,qr.y,qr.z).multiplyScalar(angle/n);return {state,e,o,angle,pos:e.length(),score:e.lengthSq()+o.lengthSq()*.16};}
 refine(seed,target,iterations=32){let q=seed.slice(),best={q:q.slice(),...this.error(q,target)};for(let it=0;it<iterations;it++){const e=this.error(q,target);if(e.score<best.score)best={q:q.slice(),...e};if(e.pos<.0008&&e.angle<.003)break;const J=Array.from({length:6},()=>Array(6).fill(0));for(let j=0;j<6;j++){const a=e.state.axes[j],d=e.state.p.clone().sub(e.state.positions[j]),v=a.clone().cross(d);J[0][j]=v.x;J[1][j]=v.y;J[2][j]=v.z;J[3][j]=a.x*.4;J[4][j]=a.y*.4;J[5][j]=a.z*.4;}const A=Array.from({length:6},(_,i)=>Array.from({length:6},(_,j)=>J[i].reduce((s,v,k)=>s+v*J[j][k],0)+(i===j?.0015:0))),b=[e.e.x,e.e.y,e.e.z,e.o.x*.4,e.o.y*.4,e.o.z*.4],u=linear(A,b);const dq=Array.from({length:6},(_,j)=>J.reduce((s,row,i)=>s+row[j]*u[i],0));const max=Math.max(...dq.map(Math.abs),.25);for(let j=0;j<6;j++)q[j]=Math.max(this.joints[j].lower,Math.min(this.joints[j].upper,q[j]+dq[j]*Math.min(1,.25/max)));}const final=this.error(q,target);if(final.score<best.score)best={q:q.slice(),...final};return best;}
 solve(target){let result=this.refine(this.q,target,18);if(result.pos>.015||result.angle>.05){const yaw=Math.atan2(target.y,target.x);for(const [a,b]of [[-.2,.1],[.3,-.5],[-.5,.5],[.7,-1.1]]){const c=Math.max(this.joints[4].lower,Math.min(this.joints[4].upper,Math.PI/2-a-b));const seed=[yaw,a,b,0,c,yaw];const r=this.refine(seed,target,45);if(r.score<result.score)result=r;if(result.pos<.002&&result.angle<.01)break;}}this.q=result.q;this.lastError=result.pos;this.lastAngle=result.angle;return result;}
}
export const ROBOT_LAYOUT_SCALE= .6;
export const ROBOT_BASE=[.15,.35,-.32];
export function targetToRobot(world){return new Vector3(world.x*.6-.15,-(world.z*.6+.32),world.y-.35);}
